(function(){const e=document.createElement("link").relList;if(e&&e.supports&&e.supports("modulepreload"))return;for(const a of document.querySelectorAll('link[rel="modulepreload"]'))n(a);new MutationObserver(a=>{for(const s of a)if(s.type==="childList")for(const l of s.addedNodes)l.tagName==="LINK"&&l.rel==="modulepreload"&&n(l)}).observe(document,{childList:!0,subtree:!0});function i(a){const s={};return a.integrity&&(s.integrity=a.integrity),a.referrerPolicy&&(s.referrerPolicy=a.referrerPolicy),a.crossOrigin==="use-credentials"?s.credentials="include":a.crossOrigin==="anonymous"?s.credentials="omit":s.credentials="same-origin",s}function n(a){if(a.ep)return;a.ep=!0;const s=i(a);fetch(a.href,s)}})();const b="Home",w="About",A="Blog",P="Book",C="Format",q="Platform",T="Days",D="Approach",S="Psychopedagogue",k="Teenagers",z="Adults",x="Behavior",J="Development",O="Learning",R="Online",j="In person",I="All",W="Contact",H="Articles",E="Share",M="ADHD",r={"Pular para o conteúdo":"Skip to content","PsicólogoCRP-08/49809":"Psychologist",Home:b,"Como funciona":"How it works",Sobre:w,Blog:A,Dúvidas:"FAQ",Agendar:P,"Atendimento psicológico online":"Online psychological care","Terapia online: um espaço de escuta, onde você estiver.":"Online therapy: a space to be heard, <em>wherever you are.</em>","A psicoterapia online é a sessão de terapia feita por videochamada, ao vivo, com um psicólogo registrado no Conselho. Você conversa de um lugar reservado, sem precisar se deslocar, com o mesmo compromisso ético e de sigilo do consultório.":"Online psychotherapy is a live therapy session by video call with a psychologist registered with the Council. You talk from a private place, without having to travel, with the same ethical and confidentiality commitment as the office.","Agendar pelo WhatsApp":"Book on WhatsApp","Entender como funciona →":"See how it works →","Junior · Psicólogo clínico":"Junior · Clinical psychologist","Role para descobrir":"Scroll to discover","Por que online":"Why online","É terapia de verdade, só que pela tela.":"It's real therapy, just through a screen.","Reconhecida pelo Conselho":"Recognized by the Council","O atendimento psicológico por meios digitais é regulamentado pelo Conselho Federal de Psicologia e segue o mesmo Código de Ética do atendimento presencial.":"Psychological care through digital means is regulated by the Federal Council of Psychology and follows the same Code of Ethics as in-person care.","Sigilo garantido":"Confidentiality guaranteed","O que é dito na sessão fica entre você e o psicólogo. O sigilo profissional é um dever ético e vale igualmente para as sessões online.":"What is said in the session stays between you and the psychologist. Professional confidentiality is an ethical duty and applies equally to online sessions.","Sem deslocamento":"No commute","Você faz a sessão de casa ou de outro lugar reservado, inclusive se estiver em outra cidade. Fica mais fácil manter a regularidade, que faz parte do processo terapêutico.":"You have the session from home or another private place, even if you're in another city. It's easier to keep a regular schedule, which is part of the therapeutic process.","Passo a passo":"Step by step","Você entra em contato":"You get in touch","Mande uma mensagem pelo WhatsApp ou pelo Direct do Instagram. Não precisa explicar tudo agora: um “olá” já é suficiente.":`Send a message on <a href="https://wa.me/5541995300225?text=Ol%C3%A1%2C%20Junior%21%20Vim%20pelo%20seu%20site%20e%20gostaria%20de%20tirar%20algumas%20d%C3%BAvidas%20sobre%20o%20atendimento." target="_blank" rel="noopener">WhatsApp</a> or via <a href="https://ig.me/m/_psicopedagogia_ativa" target="_blank" rel="noopener">Instagram Direct</a>. You don't need to explain everything now: a simple “hi” is enough.`,"Combinamos o horário":"We agree on a time","Atendimento de segunda a sábado, com horário combinado com você.":"Sessions <strong>Monday to Saturday</strong>, at a time arranged with you.","Escolhemos a plataforma":"We choose the platform","As sessões acontecem por Google Meet ou videochamada do WhatsApp. Antes do horário, você recebe o link ou a chamada.":"Sessions take place on <strong>Google Meet</strong> or <strong>WhatsApp video call</strong>. Before the session, you receive the link or the call.","A sessão acontece":"The session happens","No horário marcado, é só entrar pelo link, de um lugar onde você se sinta à vontade para falar.":"At the scheduled time, just join through the link, from a place where you feel comfortable talking.","Sobre as sessões":"About the sessions",Formato:C,"Online, por vídeo":"Online, by video",Plataforma:q,"Google Meet ou WhatsApp":"Google Meet or WhatsApp",Dias:T,"Segunda a sábado":"Monday to Saturday",Horário:"Time","A combinar":"To be arranged","Para a sessão online":"For the online session","Internet estável":"Stable internet","Celular ou computador com câmera e microfone":"Phone or computer with camera and microphone","Fone de ouvido, para mais privacidade":"Headphones, for more privacy","Um lugar reservado, onde ninguém escute":"A private place where no one can overhear","Adolescentes: o atendimento de menores de 18 anos precisa da autorização de ao menos um responsável legal.":"<strong>Teenagers:</strong> sessions for minors under 18 require authorization from at least one legal guardian.","Um espaço para você":"A space for you","Talvez você esteja aqui porque quer…":"Maybe you're here because you want…","…um lugar seguro para falar sobre o que sente.":"…a safe place to <strong>talk about how you feel</strong>.","…compreender melhor suas emoções.":"…to <strong>better understand your emotions</strong>.","…reconhecer suas próprias capacidades.":"…to <strong>recognize your own abilities</strong>.","…buscar caminhos para lidar com os desafios.":"…to find ways to <strong>deal with challenges</strong>.","Quem atende":"Who you'll talk to","Olá! Sou o Benedito, mas pode me chamar de Junior.":"Hi! I'm Benedito, but you can call me <em>Junior</em>.","Sou psicólogo clínico e psicopedagogo, com atendimentos presenciais e online para adolescentes e adultos.":"I'm a clinical psychologist and educational psychologist (psychopedagogue), seeing teenagers and adults in person and online.","Meu trabalho é baseado na construção de um vínculo terapêutico, com escuta, respeito e confiança. Quero que você encontre aqui um espaço seguro, onde possa falar sobre o que sente, compreender melhor suas emoções e reconhecer suas próprias capacidades.":"My work is based on building a therapeutic bond, with listening, respect and trust. I want you to find a safe space here, where you can talk about how you feel, better understand your emotions and recognize your own abilities.","Vamos juntos buscar caminhos para lidar com os desafios e construir uma vida com mais sentido e equilíbrio.":"Together, let's find ways to deal with challenges and build a life with more meaning and balance.","Abordagem e formação":"Approach and education",Abordagem:D,Psicanálise:"Psychoanalysis","Linha teórica que orienta o atendimento":"Theoretical framework that guides the work","Formação · Psicologia":"Education · Psychology","Psicólogo clínico":"Clinical psychologist","Formação · Psicopedagogia":"Education · Psychopedagogy",Psicopedagogo:S,"Verificar o registro CRP-08/49809 no Cadastro Nacional do CFP ↗":"Verify registration CRP-08/49809 in the CFP National Registry ↗","Para quem":"Who it's for","Quem eu atendo":"Who I see",Adolescentes:k,"Com autorização de um responsável legal.":"With authorization from a legal guardian.",Adultos:z,"Online, de onde você estiver, ou presencialmente.":"Online, wherever you are, or in person.","Temas do meu trabalho":"Topics of my work",Emoções:"Emotions",Comportamento:x,Desenvolvimento:J,Aprendizagem:O,"Como você prefere ser atendido?":"How would you like to be seen?","Onde você estiver":"Wherever you are",Online:R,"Por videochamada, de onde você estiver":"By video call, wherever you are","Sem tempo de deslocamento":"No travel time","Mesmo sigilo e ética do consultório":"Same confidentiality and ethics as the office","Agendar sessão online":"Book an online session",Presencial:j,"No consultório, frente a frente":"At the office, face to face","Para quem prefere sair de casa para a sessão":"For those who prefer to leave home for the session","Agendar sessão presencial":"Book an in-person session","Você não precisa ter tudo resolvido para começar. Uma mensagem é suficiente.":"You don't need to have everything figured out to start. <em>One message is enough.</em>","Dar o primeiro passo":"Take the first step","Perguntas frequentes":"Frequently asked questions","Dúvidas comuns":"Common questions","Não encontrou sua pergunta? Fale comigo.":`Didn't find your question? <a href="#contato">Talk to me</a>.`,"Quem é o psicólogo Junior?":"Who is the psychologist Junior?","Benedito Ferreira dos Santos Júnior, o Junior, é psicólogo clínico e psicopedagogo. Atende adolescentes e adultos online e presencialmente, em Curitiba/PR.":"Benedito Ferreira dos Santos Júnior, known as Junior, is a clinical psychologist and psychopedagogue. He sees teenagers and adults online and in person, in Curitiba, Brazil.","Qual é o número de registro profissional (CRP)?":"What is the professional registration number (CRP)?","CRP-08/49809. Você pode conferir o registro no Cadastro Nacional de Psicólogos do CFP.":'CRP-08/49809. You can check the registration in the <a href="https://cadastro.cfp.org.br/" target="_blank" rel="noopener">CFP National Registry of Psychologists</a>.',"Qual abordagem terapêutica o Junior utiliza?":"Which therapeutic approach does Junior use?","A psicanálise. O trabalho é baseado na construção de um vínculo terapêutico, com escuta, respeito e confiança.":"Psychoanalysis. The work is based on building a therapeutic bond, with listening, respect and trust.","O atendimento é presencial ou online?":"Are sessions in person or online?","Os dois. O online é feito por Google Meet ou videochamada do WhatsApp, de segunda a sábado, com horário a combinar. O presencial é na R. Filipinas, 536, Sobreloja, sala 1, Cajuru, Curitiba/PR.":"Both. Online sessions are on Google Meet or WhatsApp video call, Monday to Saturday, at a time to be arranged. In-person sessions are at R. Filipinas, 536, Sobreloja, sala 1, Cajuru, Curitiba/PR.","Para qual público é o atendimento?":"Who are the sessions for?","Adolescentes e adultos. Para menores de 18 anos, é necessária a autorização de ao menos um responsável legal.":"Teenagers and adults. For minors under 18, authorization from at least one legal guardian is required.","Quando quiser começar, é só chamar.":"Whenever you want to start, <em>just reach out.</em>","Mande uma mensagem para tirar dúvidas ou combinar a primeira sessão.":"Send a message to ask questions or arrange the first session.","Para proteger sua privacidade, prefira deixar detalhes pessoais para a sessão. Mensagens trocadas são usadas apenas para o agendamento. Veja a Política de Privacidade.":'To protect your privacy, please save personal details for the session. Messages are used only for scheduling. See the <a href="/politica-de-privacidade.html">Privacy Policy</a>.',"Junior · Psicólogo":"Junior · Psychologist","CRP-08/49809 · Atendimento online e presencial":"CRP-08/49809 · Online and in-person sessions","Política de Privacidade":"Privacy Policy","Aviso de sigilo":"Confidentiality notice","Código de Ética do Psicólogo":"Psychologist's Code of Ethics","Este site não presta atendimento de emergência. Em crise, ligue 188 (CVV) ou 192 (SAMU).":"This site does not provide emergency care. In a crisis in Brazil, call <strong>188 (CVV)</strong> or <strong>192 (SAMU)</strong>.","O conteúdo deste site é informativo e não substitui o atendimento psicológico. Cada processo terapêutico é único; este site não promete resultados. Verificar CRP no CFP.":'The content of this site is informational and does not replace psychological care. Each therapeutic process is unique; this site does not promise results. <a href="https://cadastro.cfp.org.br/" target="_blank" rel="noopener">Verify CRP at the CFP</a>.',"© 2026 Junior · Psicólogo.":"© 2026 Junior · Psychologist.","Terapia online com Junior, psicólogo (CRP-08/49809)":"Online therapy with Junior, psychologist (CRP-08/49809)","Conversas sobre emoções, comportamento e aprendizagem.":"Conversations about <em>emotions, behavior and learning.</em>","Textos para entender melhor a terapia e a si mesmo. Conteúdo informativo, que não substitui o atendimento psicológico.":"Texts to better understand therapy and yourself. Informational content that does not replace psychological care.","Buscar artigos no blog":"Search blog articles",Todos:I,"Nenhum artigo encontrado. Tente outra palavra.":"No articles found. Try another word.","Sobre o autor":"About the author","Psicólogo clínico e psicopedagogo, de abordagem psicanalítica. Atende adolescentes e adultos online e presencialmente, em Curitiba/PR.":"Clinical psychologist and psychopedagogue with a psychoanalytic approach. Sees teenagers and adults online and in person, in Curitiba, Brazil.","Conhecer o Junior →":"Meet Junior →","Verificar CRP no CFP ↗":"Verify CRP at the CFP ↗","Blog · Junior, psicólogo (CRP-08/49809)":"Blog · Junior, psychologist (CRP-08/49809)",Início:"Home","Compartilhar:":"Share:","Copiar link":"Copy link","Neste artigo":"In this article","Este conteúdo é informativo e não substitui avaliação ou acompanhamento psicológico. Em crise, ligue 188 (CVV), 24h, ou 192 (SAMU).":"This content is informational and does not replace psychological assessment or care. In a crisis in Brazil, call <strong>188 (CVV)</strong>, 24h, or <strong>192 (SAMU)</strong>.","Gostaria de conversar? Uma mensagem é suficiente.":"Would you like to talk? <em>One message is enough.</em>","Falar no WhatsApp":"Chat on WhatsApp","Continue lendo":"Keep reading","Leia também":"Read also","← Voltar ao site":"← Back to the site","LGPD · Lei nº 13.709/2018":"LGPD · Brazilian Law No. 13,709/2018","Política de Privacidade e Aviso de Sigilo":"Privacy Policy and Confidentiality Notice","1. Quem é o responsável pelos seus dados":"1. Who is responsible for your data","O controlador dos dados pessoais tratados por meio deste site e do atendimento é o psicólogo Benedito Ferreira dos Santos Júnior, CRP-08/49809, com endereço profissional em R. Filipinas, 536, Sobreloja, sala 1, Cajuru, Curitiba/PR, CEP 82960-180.":"The controller of the personal data processed through this site and in the sessions is the psychologist Benedito Ferreira dos Santos Júnior, CRP-08/49809, with professional address at R. Filipinas, 536, Sobreloja, sala 1, Cajuru, Curitiba/PR, CEP 82960-180, Brazil.","Contato para assuntos de privacidade: WhatsApp (41) 99530-0225.":'Privacy contact: WhatsApp <a href="https://wa.me/5541995300225">(41) 99530-0225</a>.',"2. Quais dados são coletados":"2. What data is collected","Pelo site: este site não tem formulários, não utiliza ferramentas de análise ou publicidade. As escolhas de idioma e de modo escuro ficam salvas apenas no seu navegador.":"<strong>Through the site:</strong> this site has no forms and uses no analytics or advertising tools. Your language and dark mode choices are saved only in your browser.","Serviços de terceiros: ao carregar as páginas, o serviço de hospedagem (Vercel) e o Google Fonts (fontes do site) podem registrar dados técnicos, como endereço IP e navegador.":"<strong>Third-party services:</strong> when pages load, the hosting service (Vercel) and Google Fonts (the site's fonts) may log technical data, such as IP address and browser.","Contato: ao chamar pelo WhatsApp ou telefone, são tratados seu nome, número de telefone e o conteúdo das mensagens.":"<strong>Contact:</strong> when you reach out on WhatsApp or by phone, your name, phone number and message content are processed.","Atendimento: durante o processo terapêutico, são produzidas informações sobre sua saúde, que a LGPD classifica como dados pessoais sensíveis.":"<strong>Sessions:</strong> during the therapeutic process, information about your health is produced, which the LGPD classifies as <em>sensitive personal data</em>.","3. Para que os dados são usados":"3. What the data is used for","Responder ao seu contato e agendar sessões;":"Replying to your contact and scheduling sessions;","Realizar o atendimento psicológico e manter os registros exigidos pelo Conselho Federal de Psicologia;":"Providing psychological care and keeping the records required by the Federal Council of Psychology;","Cumprir obrigações legais e regulatórias (por exemplo, emissão de recibos).":"Complying with legal and regulatory obligations (for example, issuing receipts).","Seus dados não são vendidos, não são usados para publicidade e não são compartilhados com terceiros, exceto quando a lei exigir.":"Your data is not sold, not used for advertising and not shared with third parties, except when required by law.","4. Bases legais":"4. Legal bases","O tratamento se apoia na execução de contrato e em procedimentos preliminares (art. 7º, V, da LGPD), no cumprimento de obrigação legal ou regulatória (art. 7º, II, e art. 11, II, “a”) e na tutela da saúde, em procedimento realizado por profissional de saúde (art. 11, II, “f”).":"Processing is based on the performance of a contract and preliminary procedures (art. 7, V, of the LGPD), compliance with a legal or regulatory obligation (art. 7, II, and art. 11, II, “a”) and the protection of health, in a procedure carried out by a health professional (art. 11, II, “f”).","5. Por quanto tempo os dados ficam guardados":"5. How long data is kept","As mensagens de agendamento são mantidas apenas pelo tempo necessário. Os registros do atendimento são guardados pelo prazo mínimo definido pelo Conselho Federal de Psicologia, em local seguro e com acesso restrito ao psicólogo.":"Scheduling messages are kept only as long as necessary. Session records are kept for the minimum period set by the Federal Council of Psychology, in a secure place with access restricted to the psychologist.","6. Aviso de sigilo":"6. Confidentiality notice","Tudo o que é dito nas sessões, presenciais ou online, é protegido pelo sigilo profissional previsto no Código de Ética Profissional do Psicólogo. As informações só podem ser compartilhadas nas exceções previstas no próprio Código, sempre na medida estritamente necessária.":"Everything said in sessions, in person or online, is protected by the professional confidentiality set out in the Psychologist's Code of Professional Ethics. Information may only be shared in the exceptions provided for in the Code itself, always to the strictly necessary extent.","No atendimento online, o psicólogo realiza as sessões de um ambiente reservado. Recomendamos que você também participe de um local privado, com fone de ouvido, e evite redes de Wi-Fi públicas.":"In online sessions, the psychologist works from a private setting. We recommend that you also join from a private place, with headphones, and avoid public Wi-Fi networks.","As sessões online são feitas por Google Meet ou videochamada do WhatsApp.":"Online sessions take place on Google Meet or WhatsApp video call.","Mensagens de WhatsApp não fazem parte da sessão. Por segurança, prefira tratar assuntos pessoais durante o atendimento.":"WhatsApp messages are not part of the session. For safety, please discuss personal matters during the session.","7. Seus direitos":"7. Your rights","Pela LGPD (art. 18), você pode pedir: confirmação de que seus dados são tratados, acesso, correção, anonimização ou eliminação dos dados desnecessários, informação sobre compartilhamento e revogação do consentimento, quando aplicável. Alguns registros não podem ser apagados antes do prazo legal de guarda.":"Under the LGPD (art. 18), you may request: confirmation that your data is processed, access, correction, anonymization or deletion of unnecessary data, information about sharing, and withdrawal of consent, where applicable. Some records cannot be deleted before the legal retention period.","Para exercer seus direitos, use o contato indicado no item 1 (WhatsApp). Você também pode recorrer à Autoridade Nacional de Proteção de Dados (ANPD), em gov.br/anpd.":`To exercise your rights, use the contact given in item 1 (WhatsApp). You may also contact Brazil's National Data Protection Authority (ANPD) at <a href="https://www.gov.br/anpd" target="_blank" rel="noopener">gov.br/anpd</a>.`,"8. Emergências":"8. Emergencies","Este site e o atendimento online não se destinam a situações de emergência. Em caso de crise, ligue 188 (CVV), 192 (SAMU) ou procure o pronto-socorro mais próximo.":"This site and online sessions are not intended for emergencies. In a crisis in Brazil, call <strong>188 (CVV)</strong>, <strong>192 (SAMU)</strong> or go to the nearest emergency room.",Contato:W,"Política de Privacidade e Sigilo · Junior, psicólogo (CRP-08/49809)":"Privacy and Confidentiality Policy · Junior, psychologist (CRP-08/49809)","Início: Junior, psicólogo":"Home: Junior, psychologist",Seções:"Sections","Modo escuro":"Dark mode","Abrir menu":"Open menu","Fechar menu":"Close menu","Junior, psicólogo, sorrindo no alto de uma montanha, com um vale verde ao fundo.":"Junior, psychologist, smiling on a mountaintop with a green valley behind him.","Junior, psicólogo, sorrindo à beira-mar com um cachorro branco no colo.":"Junior, psychologist, smiling by the sea holding a white dog.","Chamada para agendamento":"Booking call to action","Conversar no WhatsApp":"Chat on WhatsApp","Buscar artigos…":"Search articles…","Filtrar por categoria":"Filter by category",Artigos:H,"Junior, psicólogo":"Junior, psychologist","Você está em":"You are here",Compartilhar:E,"Voltar ao início":"Back to home","Link copiado!":"Link copied!","Não foi possível copiar":"Couldn't copy","Psicologia social e espiritualidade":"Social psychology and spirituality",TDAH:M,"O resgate do sagrado no manejo social: uma abordagem junguiana para as crises da pós-modernidade":"Restoring the sacred in social care: a Jungian approach to the crises of postmodernity","Por que integrar a espiritualidade, compreendida pela ótica de Carl Gustav Jung, é uma necessidade clínica, ética e política no manejo social contemporâneo.":"Why integrating spirituality, understood through the lens of Carl Gustav Jung, is a clinical, ethical and political necessity in contemporary social care.","9 de novembro de 2026 · 5 min de leitura":'<time datetime="2026-11-09">November 9, 2026</time> · 5 min read',"9 de novembro de 2026 · 3 min de leitura":'<time datetime="2026-11-09">November 9, 2026</time> · 3 min read',"Por Junior · CRP-08/49809 · 9 de novembro de 2026 · 3 min de leitura":'By <strong>Junior</strong> · CRP-08/49809 · <time datetime="2026-11-09">November 9, 2026</time> · 3 min read',"Por Junior · CRP-08/49809 · 9 de novembro de 2026 · 5 min de leitura":'By <strong>Junior</strong> · CRP-08/49809 · <time datetime="2026-11-09">November 9, 2026</time> · 5 min read',"A ligação entre TDAH e dependência: comportamentos aditivos em adultos":"The link between ADHD and addiction: addictive behaviors in adults","Por que adultos com TDAH correm mais risco de dependência, como reconhecer os sinais cedo e quando procurar ajuda.":"Why adults with ADHD are at greater risk of addiction, how to recognize the signs early and when to seek help.","A ligação entre TDAH e dependência: comportamentos aditivos em adultos · Junior, psicólogo":"The link between ADHD and addiction: addictive behaviors in adults · Junior, psychologist","O resgate do sagrado no manejo social: uma abordagem junguiana para as crises da pós-modernidade · Junior, psicólogo":"Restoring the sacred in social care: a Jungian approach to the crises of postmodernity · Junior, psychologist","Comportamentos aditivos e TDAH":"Addictive behaviors and ADHD","Comportamentos aditivos com substâncias químicas":"Addictive behaviors with chemical substances","Estimulantes e o cérebro com TDAH":"Stimulants and the ADHD brain","Muitos adultos com TDAH apresentam comportamentos aditivos: dependência de comida, maconha, internet. Aprenda a identificar os sinais de dependência precocemente e a distinguir os diferentes tipos de dependência para superar os desejos incontroláveis.":"Many adults with ADHD show addictive behaviors: dependence on food, marijuana, the internet. Learn to identify the signs of addiction early and to distinguish the different types of addiction in order to overcome uncontrollable cravings.","Lidar bem com o TDAH é um processo desafiador. Torna-se ainda mais difícil quando há uma dependência química ou comportamental concomitante. Muitos adultos com TDAH lutam contra comportamentos aditivos, que frequentemente não são reconhecidos nem tratados. Não existe uma ligação genética direta entre comportamentos aditivos e TDAH.":"Managing ADHD well is a challenging process. It becomes even harder when there is a co-occurring chemical or behavioral addiction. Many adults with ADHD struggle with addictive behaviors that often go unrecognized and untreated. There is no direct genetic link between addictive behaviors and ADHD.","Os transtornos aditivos são complexos e frequentemente causados por fatores comportamentais, emocionais e de vida. A busca por emoções fortes, a necessidade de gratificação imediata e a procura por novas experiências prazerosas são mais comuns em muitas pessoas com TDAH. Estressores da vida, como perda de emprego e dificuldades financeiras, são mais frequentes em pessoas com TDAH e são fatores de risco para o uso de substâncias e outros comportamentos aditivos.":"Addictive disorders are complex and often caused by behavioral, emotional and life factors. Thrill-seeking, the need for immediate gratification and the search for new pleasurable experiences are more common in many people with ADHD. Life stressors, such as job loss and financial difficulties, are more frequent in people with ADHD and are risk factors for substance use and other addictive behaviors.","Inicialmente, os comportamentos viciantes proporcionam uma descarga de dopamina que é muito satisfatória para o circuito de recompensa do cérebro. Com o tempo, a “euforia” desaparece, mas o comportamento viciante continua devido a desejos físicos ou emocionais. Alguns indicadores de dependência são:":"At first, addictive behaviors provide a rush of dopamine that is very satisfying to the brain's reward circuit. Over time, the “high” fades, but the addictive behavior continues because of physical or emotional cravings. Some indicators of addiction are:","Desejos intensos e urgentes pela substância ou comportamento. Estes podem incluir desejos físicos (álcool, cocaína) ou desejos emocionais (jogos de azar), ou ambos.":"<strong>Intense, urgent cravings for the substance or behavior.</strong> These may include physical cravings (alcohol, cocaine) or emotional cravings (gambling), or both.","Nenhum controle sobre o consumo. É por isso que uma bebida leva a sete, e 30 minutos de videogame se transformam em cinco horas (ou uma noite inteira).":"<strong>No control over consumption.</strong> That is why one drink leads to seven, and 30 minutes of video games turn into five hours (or a whole night).","Uso contínuo apesar das consequências negativas. Às vezes, isso envolve negação (“Eu não tenho um problema com a bebida”), mas muitos indivíduos estão cientes dos problemas causados por seus comportamentos aditivos e mesmo assim continuam com eles.":"<strong>Continued use despite negative consequences.</strong> Sometimes this involves denial (“I don't have a drinking problem”), but many individuals are aware of the problems caused by their addictive behaviors and continue them anyway.","Incapacidade de interromper os comportamentos, apesar do desejo de fazê-lo. Quando isso acontece, é hora de procurar um terapeuta especializado em trabalhar com pessoas com vícios.":"<strong>Inability to stop the behaviors, despite wanting to.</strong> When this happens, it is time to seek a therapist who specializes in working with people with addictions.","Abaixo estão alguns vícios comuns em substâncias químicas, comportamentos e alimentos. Esses são problemas potenciais para todos, mas os riscos são maiores para adultos com TDAH.":"Below are some common addictions to chemical substances, behaviors and food. These are potential problems for everyone, but the risks are greater for adults with ADHD.","A incidência de problemas com o uso de substâncias ao longo da vida entre adultos na população geral é de aproximadamente 25%. Eles podem ser viciados em álcool, drogas recreativas ou medicamentos prescritos. Em comparação, 50% dos adultos com TDAH têm histórico de problemas com o uso de substâncias em algum momento de suas vidas.":"The lifetime incidence of substance use problems among adults in the general population is about 25%. They may be addicted to alcohol, recreational drugs or prescription medication. By comparison, 50% of adults with ADHD have a history of substance use problems at some point in their lives.","Muitas razões explicam os vícios entre adultos com TDAH, porém duas causas gerais surgem repetidamente. Primeiro, adultos com TDAH são mais propensos à automedicação, principalmente quando não têm consciência ou compreensão da biologia do TDAH e ainda não aprenderam a lidar bem com ele. Segundo, muitos adultos com TDAH são atraídos por experiências novas e emocionantes. Um indivíduo disse que gostava de “brincar” com o próprio cérebro.":"Many reasons explain addictions among adults with ADHD, but two general causes come up again and again. First, adults with ADHD are more prone to self-medication, especially when they are not aware of or don't understand the biology of ADHD and have not yet learned to manage it well. Second, many adults with ADHD are drawn to new and exciting experiences. One person said they liked to “play” with their own brain.","Muitos adultos com TDAH se automedicam com grandes quantidades de cafeína diariamente. Alguns se automedicam com nicotina, seja fumando cigarros ou usando cigarros eletrônicos. Outros estimulantes que são abusados incluem cocaína, metanfetamina, MDMA (ecstasy) e efedrina. Todas essas substâncias representam sérios riscos à saúde (incluindo a cafeína em grandes quantidades), e algumas podem levar a consequências fatais. Os “benefícios” temporários dessas drogas são limitados e são amplamente superados pelos graves riscos à saúde e à vida.":"Many adults with ADHD self-medicate with large amounts of caffeine every day. Some self-medicate with nicotine, either by smoking cigarettes or using e-cigarettes. Other stimulants that are abused include cocaine, methamphetamine, MDMA (ecstasy) and ephedrine. All of these substances pose serious health risks (including caffeine in large amounts), and some can have fatal consequences. The temporary “benefits” of these drugs are limited and far outweighed by the serious risks to health and life.","O vazio da razão tecnodirigida":"The emptiness of technology-driven reason","O “Espírito desta Época” versus o “Espírito das Profundezas”":"The “Spirit of This Time” versus the “Spirit of the Depths”","A habitação do sagrado e a integração dos opostos":"The dwelling of the sacred and the integration of opposites","Conclusão: o templo invisível do manejo social":"Conclusion: the invisible temple of social care","Questões para reflexão e diálogo":"Questions for reflection and dialogue","“Nossa época está buscando uma nova fonte de vida. Eu encontrei uma e bebi dela e a água tinha gosto bom.”[1] C. G. Jung":'“Our age is seeking a new spring of life. I found one and drank of it and the water tasted good.”<sup><a href="#ref-1">[1]</a></sup> C. G. Jung',"Vivemos sob a égide do que o sociólogo Max Weber denominou a “jaula de ferro” da modernidade: um modelo de sociedade impulsionado pela eficácia técnica, pelo utilitarismo econômico e pelo racionalismo instrumental. No entanto, ao despojar o tecido social de seus mitos, rituais e dimensões transcendentes, a pós-modernidade não entregou a libertação prometida; em seu lugar, instaurou um estado de desabrigo espiritual e Angst (ansiedade existencial coletiva).":"We live under the aegis of what the sociologist Max Weber called the “iron cage” of modernity: a model of society driven by technical efficiency, economic utilitarianism and instrumental rationalism. Yet by stripping the social fabric of its myths, rituals and transcendent dimensions, postmodernity did not deliver the liberation it promised; in its place, it established a state of spiritual homelessness and <i>Angst</i> (collective existential anxiety).","No manejo social contemporâneo, seja na formulação de políticas públicas, na gestão de crises comunitárias ou na mediação de conflitos, persiste a ilusão de que a complexidade humana pode ser resolvida exclusivamente por parâmetros estatísticos, burocráticos ou comportamentais. Ignora-se, contudo, que o ser humano é inevitavelmente um homo religiosus. Defendo que a integração da espiritualidade, desvinculada de dogmatismos institucionais e compreendida através da ótica de Carl Gustav Jung, não é um luxo místico, mas uma necessidade clínica, ética e política indispensável para a sustentabilidade do manejo social.":"In contemporary social care, whether in shaping public policy, managing community crises or mediating conflicts, there persists the illusion that human complexity can be resolved solely through statistical, bureaucratic or behavioral parameters. What is ignored, however, is that the human being is inevitably a <i>homo religiosus</i>. I argue that integrating spirituality, detached from institutional dogmatism and understood through the lens of Carl Gustav Jung, is not a mystical luxury but a clinical, ethical and political necessity indispensable to the sustainability of social care.","Em sua obra monumental Liber Novus (O Livro Vermelho), Jung estabelece uma distinção crucial entre o “Espírito desta Época” e o “Espírito das Profundezas”. O primeiro rege a lógica pragmática, o progresso material, as convenções sociais e o intelecto racional. O segundo comanda os estratos atemporais e arquetípicos da psique, onde residem os anseios de sentido, a intuição do sagrado e a busca pela totalidade.":"In his monumental work <i>Liber Novus</i> (The Red Book), Jung draws a crucial distinction between the “Spirit of This Time” and the “Spirit of the Depths”. The first governs pragmatic logic, material progress, social conventions and the rational intellect. The second commands the timeless, archetypal layers of the psyche, where the longing for meaning, the intuition of the sacred and the search for wholeness reside.","Quando as estruturas de gestão social operam unicamente sob o Espírito desta Época, elas tratam o indivíduo como uma mera engrenagem produtiva ou um vetor de dados. A consequência direta dessa dessacralização é a perda da anima mundi (a alma do mundo). Como advertiu Jung, quando a função religiosa da psique é reprimida pelo cientificismo materialista, o impulso espiritual não desaparece; ele se desloca para o inconsciente coletivo, reaparecendo de forma destrutiva na forma de psicoses de massa, polarizações ideológicas cegas, consumismo compulsivo e epidemias de burnout.":"When social management structures operate solely under the Spirit of This Time, they treat the individual as a mere productive cog or a data vector. The direct consequence of this desacralization is the loss of the <i>anima mundi</i> (the soul of the world). As Jung warned, when the religious function of the psyche is repressed by materialist scientism, the spiritual impulse does not disappear; it shifts into the collective unconscious, reappearing destructively as mass psychoses, blind ideological polarization, compulsive consumerism and epidemics of burnout.","Integrar a espiritualidade no manejo social significa reconhecer que o bem-estar comunitário exige o cultivo de recipientes simbólicos que acolham o Espírito das Profundezas.":"Integrating spirituality into social care means recognizing that community well-being requires cultivating symbolic vessels that can hold the Spirit of the Depths.","No pensamento junguiano, a experiência espiritual autêntica não aliena o indivíduo da realidade terrena; ao contrário, fundamenta-o. A espiritualidade psíquica baseia-se na coincidentia oppositorum: a união consciente dos opostos (luz e sombra, razão e emoção, o indivíduo e o coletivo).":"In Jungian thought, authentic spiritual experience does not alienate the individual from earthly reality; on the contrary, it grounds them. Psychic spirituality rests on the <i>coincidentia oppositorum</i>: the conscious union of opposites (light and shadow, reason and emotion, the individual and the collective).","No manejo social tradicional, o “mal”, a marginalidade e o sofrimento são frequentemente tratados por meio da exclusão ou da supressão puritana. Sob a ótica junguiana, o manejo social eficaz exige o reconhecimento da Sombra coletiva. A dimensão espiritual introduz uma ética da compaixão e da responsabilidade.":"In traditional social care, “evil”, marginality and suffering are often dealt with through exclusion or puritanical suppression. From a Jungian perspective, effective social care requires recognizing the collective Shadow. The spiritual dimension introduces an ethic of compassion and responsibility.","O indivíduo que reconhece sua própria sombra torna-se incapaz de projetar o bode expiatório no outro.":"The individual who recognizes their own shadow becomes unable to project the scapegoat onto the other.","Além disso, Jung argumenta que a renovação cultural depende do processo de individuação: a realização do Si Mesmo (Self). Quando o manejo social passa a respeitar a jornada de integração espiritual de cada sujeito, ele deixa de impor uma padronização coercitiva e passa a criar ambientes sociais que nutrem a autonomia psíquica, a alteridade e o pertencimento comunitário.":"Furthermore, Jung argues that cultural renewal depends on the process of individuation: the realization of the <i>Self</i>. When social care comes to respect each person's journey of spiritual integration, it stops imposing coercive standardization and begins to create social environments that nurture psychic autonomy, otherness and community belonging.","O resgate da espiritualidade no manejo das relações humanas não propõe o abandono da razão ou da ciência, mas a sua coroação por um sentido maior. Como Jung apontou ao analisar o mito de Izdubar no Livro Vermelho, o veneno do excesso de racionalismo só pode ser curado quando reintroduzimos o ovo da imaginação, do símbolo e do sagrado em nossas vidas.":"Restoring spirituality in the care of human relationships does not mean abandoning reason or science, but crowning them with a greater meaning. As Jung pointed out when analyzing the myth of Izdubar in The Red Book, the poison of excessive rationalism can only be healed when we reintroduce the egg of imagination, symbol and the sacred into our lives.","Um manejo social genuinamente humanizado deve atuar como uma ecclesia spiritualis: não uma instituição dogmática, mas um espaço relacional sagrado onde a dor individual ganha significado e o desenvolvimento humano é compreendido como uma contínua encarnação do espírito na matéria. Cuidar do social sem cuidar da alma é construir sobre a areia. Reintegrar o sagrado é a única via para restaurar a dignidade humana e curar o trauma de nossa época.":"Truly humanized social care should act as an <i>ecclesia spiritualis</i>: not a dogmatic institution, but a sacred relational space where individual pain gains meaning and human development is understood as an ongoing incarnation of spirit in matter. Caring for the social without caring for the soul is building on sand. Reintegrating the sacred is the only way to restore human dignity and heal the trauma of our time.","Diagnóstico institucional e social":"Institutional and social diagnosis","O domínio da técnica: em que medida as práticas de intervenção ou manejo social de sua organização/comunidade estão reféns do “Espírito desta Época” (pragmatismo, métricas frias e produtivismo) em detrimento da escuta do “Espírito das Profundezas” (sentido, valores e acolhimento humano)?":"<strong>The dominance of technique:</strong> to what extent are the intervention or social care practices of your organization/community held hostage by the “Spirit of This Time” (pragmatism, cold metrics and productivism) at the expense of listening to the “Spirit of the Depths” (meaning, values and human care)?","A repressão do sagrado: quais são os “dragões e demônios” (anomia, esgotamento, violência, apatia) que têm surgido em seu ambiente social como sintoma da falta de um espaço para a expressão da dimensão espiritual e simbólica?":"<strong>The repression of the sacred:</strong> what “dragons and demons” (anomie, exhaustion, violence, apathy) have been emerging in your social environment as a symptom of the lack of space to express the spiritual and symbolic dimension?","Ética, sombra e alteridade":"Ethics, shadow and otherness","Reconhecimento da sombra coletiva: ao lidar com conflitos sociais ou comunitários, de que maneira a tendência de “demonizar o outro” reflete a projeção da nossa própria sombra não integrada? Como a espiritualidade junguiana pode transformar essa dinâmica?":"<strong>Recognizing the collective shadow:</strong> when dealing with social or community conflicts, how does the tendency to “demonize the other” reflect the projection of our own unintegrated shadow? How can Jungian spirituality transform this dynamic?","Respeito à individuação: o ecossistema social no qual você atua favorece o desenvolvimento autêntico da singularidade dos indivíduos (individuação) ou pressiona pela massificação e adaptação cega aos padrões estabelecidos?":"<strong>Respect for individuation:</strong> does the social ecosystem you work in foster the authentic development of each individual's uniqueness (individuation), or does it push toward massification and blind conformity to established standards?","Ação prática e renovação":"Practical action and renewal","Construção do recipiente alquímico: que rituais, espaços de fala, práticas simbólicas ou espaços de descompressão podem ser implementados hoje no seu manejo social para atuar como uma “catedral interior” e restaurar o sentido do trabalho coletivo?":"<strong>Building the alchemical vessel:</strong> what rituals, spaces for speaking, symbolic practices or spaces for decompression could be put in place today in your social care work to act as an “inner cathedral” and restore the meaning of collective work?","O mito pessoal e coletivo: qual é o mito subjacente que guia a sua atuação no campo social? Esse mito ainda oferece água viva para a sua alma e para a comunidade atendida?":"<strong>The personal and collective myth:</strong> what is the underlying myth that guides your work in the social field? Does this myth still offer living water to your soul and to the community you serve?","[1] JUNG, C. G. O Livro Vermelho: Liber Novus. Organização de Sonu Shamdasani; tradução de Edgar Orth. Petrópolis: Vozes, 2016.":"[1] JUNG, C. G. <i>O Livro Vermelho: Liber Novus</i> (The Red Book). Edited by Sonu Shamdasani; Portuguese translation by Edgar Orth. Petrópolis: Vozes, 2016."},d=document.documentElement,h=document.querySelector("[data-tema]"),g=()=>h.setAttribute("aria-pressed",d.dataset.theme==="dark");g();h.addEventListener("click",()=>{d.dataset.theme=d.dataset.theme==="dark"?"light":"dark";try{localStorage.tema=d.dataset.theme}catch{}g()});let t=!1;const B=o=>t&&r[o]||o,F=o=>o.replace(/\s+/g," ").trim(),f=(o,e=[])=>{for(const i of o.children)i.translate===!1||["SCRIPT","STYLE","svg","NOSCRIPT"].includes(i.tagName)||([...i.childNodes].some(n=>n.nodeType===3&&n.textContent.trim())?e.push(i):f(i,e));return e},p=["aria-label","alt","placeholder","title"],u=[],m=document.title,N=()=>{for(const o of f(document.body)){const e=r[F(o.textContent)];if(!e)continue;const i=o.innerHTML;u.push(()=>{o.innerHTML=i}),e.includes("<")?o.innerHTML=e:[...o.childNodes].find(n=>n.nodeType===3&&n.textContent.trim()).textContent=e}for(const o of document.querySelectorAll(p.map(e=>`[${e}]:not([data-lang])`).join()))for(const e of p){const i=o.getAttribute(e);!i||!r[i]||(u.push(()=>o.setAttribute(e,i)),o.setAttribute(e,r[i]))}document.title=r[m]||m},c=document.querySelector("[data-lang]"),v=o=>{t=o,t?N():(u.splice(0).forEach(e=>e()),document.title=m),d.lang=t?"en":"pt-BR",c.textContent=t?"PT":"EN",c.lang=t?"pt":"en",c.setAttribute("aria-label",t?"Ler em português":"Read in English")};let y=null;try{y=localStorage.idioma}catch{}y==="en"&&v(!0);c.addEventListener("click",()=>{v(!t);try{localStorage.idioma=t?"en":"pt"}catch{}});export{B as t};
